#include <bits/stdc++.h>
using namespace std;
constexpr int MOD=998244353, ROOT=3;
int powmod(int a,int b){long long r=1,x=a;while(b){if(b&1)r=r*x%MOD;x=x*x%MOD;b>>=1;}return (int)r;}
void ntt(vector<int>& a,bool inverse){int n=(int)a.size();for(int i=1,j=0;i<n;++i){int bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j)swap(a[i],a[j]);}for(int len=2;len<=n;len<<=1){int wlen=powmod(ROOT,(MOD-1)/len);if(inverse)wlen=powmod(wlen,MOD-2);for(int i=0;i<n;i+=len){long long w=1;for(int j=0;j<len/2;j++){int u=a[i+j],v=(long long)a[i+j+len/2]*w%MOD;int x=u+v;if(x>=MOD)x-=MOD;int y=u-v;if(y<0)y+=MOD;a[i+j]=x;a[i+j+len/2]=y;w=w*wlen%MOD;}}}if(inverse){int invn=powmod(n,MOD-2);for(int& x:a)x=(long long)x*invn%MOD;}}
int main(){int T=1000000;int L=6*(T+1)+5;vector<unsigned char> prime(L+1,true);prime[0]=prime[1]=false;for(int p=2;p*p<=L;++p)if(prime[p])for(int j=p*p;j<=L;j+=p)prime[j]=false;int n=1;while(n<2*(T+2))n<<=1;vector<int>f(n),g(n);for(int i=1;i<=T+1;++i)f[i]=prime[6*i-1];for(int i=1;i<=T;++i)g[i]=f[i]&&f[i+1];ntt(f,false);ntt(g,false);for(int i=0;i<n;++i)f[i]=(long long)f[i]*g[i]%MOD;ntt(f,true);int failures=0,ext=0,minall=INT_MAX;for(int i=2;i<=T;++i){if(!prime[6*i-1])++ext;if(f[i]==0)++failures;minall=min(minall,f[i]);}cout<<"T="<<T<<" extinction="<<ext<<" failures="<<failures<<" global_min="<<minall<<"\n";for(int t: {2,6,92,136,1000,10000,100000,1000000})cout<<t<<" "<<f[t]<<"\n";}
